questionvariables.text:
/* Number of schools in each village. */
na:4+rand(3);
nb:4+rand(3);
nc:4+rand(3);
n:na+nb+nc;

/* Randomise which village gains, loses or remains stable. */
village_codes:random_permutation([1,2,3]);

/* All three villages have overlapping Year 1 values. */

/* Generate n distinct measurements, with small irregular gaps. */
base:60+rand(11);

gaps:makelist(1+rand(3),i,1,n-1);

book_levels:makelist(
    base+sum(gaps[j],j,1,i-1),
    i,1,n
);

/* Randomise which measurements belong to each village. */
mixed:random_permutation(book_levels);

/* Sort measurements so that the gaining village starts
   with two low values and the losing village with two high values. */
ordered:sort(mixed);

low_values:[ordered[1],ordered[2]];
high_values:[ordered[n-1],ordered[n]];

/* Distribute the remaining measurements among all three villages. */
middle:random_permutation(
    makelist(ordered[i],i,3,n-2)
);

a0:append(
    low_values,
    makelist(middle[i],i,1,na-2)
);

b0:append(
    high_values,
    makelist(middle[na-2+i],i,1,nb-2)
);

c0:makelist(
    middle[na+nb-4+i],
    i,1,nc
);

/* Exchange low and high values between villages.
   Shuffle within villages to create individual changes. */
a1:random_permutation(
    append(
        high_values,
        makelist(a0[i],i,3,na)
    )
);

b1:random_permutation(
    append(
        low_values,
        makelist(b0[i],i,3,nb)
    )
);

c1:random_permutation(c0);

/* Construct the school records. */
ra:makelist(
    [i,village_codes[1],a0[i],a1[i]],
    i,1,na
);

rb:makelist(
    [na+i,village_codes[2],b0[i],b1[i]],
    i,1,nb
);

rc:makelist(
    [na+nb+i,village_codes[3],c0[i],c1[i]],
    i,1,nc
);

rows:random_permutation(append(ra,rb,rc));

/* Arrays for JSXGraph, padded to 18 schools. */
ids:makelist(
    if i<=n then rows[i][1] else 0,
    i,1,18
);

villages:makelist(
    if i<=n then rows[i][2] else 0,
    i,1,18
);

before:makelist(
    if i<=n then rows[i][3] else 0,
    i,1,18
);

after:makelist(
    if i<=n then rows[i][4] else 0,
    i,1,18
);

/* Individual changes. */
changes:makelist(
    rows[i][4]-rows[i][3],
    i,1,n
);

/* Numerical answers. */
ta_gained:sum(
    if changes[i]>0 then 1 else 0,
    i,1,n
);

ta_lost:sum(
    if changes[i]<0 then 1 else 0,
    i,1,n
);

ta_unchanged:sum(
    if changes[i]=0 then 1 else 0,
    i,1,n
);

ta_maxgain:lmax(changes);
ta_maxloss:-lmin(changes);

ta_total_schools:n;
ta_unequal_schools:ta_gained+ta_lost;

/* Village-level mean changes. */
ta_mean_gain:
    (sum(a1[i],i,1,na)-sum(a0[i],i,1,na))/na;

ta_mean_loss:
    (sum(b1[i],i,1,nb)-sum(b0[i],i,1,nb))/nb;

ta_mean_stable:0;

/* The gaining village always has the largest mean increase. */
ta_village:village_codes[1];
ta_villageB:village_codes[2];
ta_villageC:village_codes[3];

/* Values for diagnostic feedback. */
ta_year1_max:lmax(append(a0,b0,c0));
ta_max_year2:lmax(append(a1,b1,c1));

/* Dropdown for Question 3. */
ta_village_options:[
    [1,is(ta_village=1),"Village A"],
    [2,is(ta_village=2),"Village B"],
    [3,is(ta_village=3),"Village C"]
];

/* Final conceptual dropdown. */
ta_conclusion_options:[
    [1,false,
     "The identical boxplots mean every school stayed roughly the same."],
    [2,false,
     "Every school experienced approximately the same change."],
    [3,true,
     "The overall distributions are identical, but individual and village-level changes can differ."],
    [4,false,
     "The village with the most books in Year 2 necessarily had the largest increase."]
];
